// Foundation-owned. Generated by hand from contracts/schema/*.json and kept in step
// with them. No track modifies this file; a mismatch with the JSON Schema is a
// contract gap — record it in NOTES.md and report.

export type ISO8601 = string;

export type Relationship = {
  contact_id: string; display: string; is_group: boolean;
  message_count: number; sent_count: number; received_count: number;
  first_contact_at: ISO8601 | null; last_contact_at: ISO8601 | null;
  days_since_last_contact: number;
  momentum_90d: number; initiation_ratio: number;
  median_reply_latency_s?: { user: number | null; them: number | null };
  p90_reply_latency_s?: { user: number | null; them: number | null };
  tapbacks?: { given: number; received: number };
  muted_by_them?: boolean | null;
  green_share?: number;
  calls?: { count: number; total_seconds: number; initiated_by_user: number; missed: number };
  archetype: null | "fade" | "chapter" | "one_way_enthusiasm" | "the_one_you_keep_waiting" | "rising_fastest";
  as_of: ISO8601;
};

export type Digest = {
  schema_version: "digest.v1";
  user_id: string; device_id: string; generated_at: ISO8601;
  corpus: {
    message_count: number; thread_count: number;
    first_message_at: ISO8601 | null; last_message_at: ISO8601 | null;
    span_days: number; green_share?: number;
    messages_in_icloud?: boolean | null;
    retention_boundary?: null | "30d" | "365d" | "1y_exact" | "30d_exact";
    days_since_newest?: number;
    health: "healthy" | "fixable" | "thin";
    health_reasons?: string[];
    as_of: ISO8601;
  };
  relationships: Relationship[];
  whole_life: Record<string, unknown> & { as_of: ISO8601 };
};

/** Phase 2's bounded understanding block. Derived on-device from both sides; never a quote. */
export type ContextualExemplar = {
  text: string; answered: "question_from_them" | "statement_from_them" | "plan_unresolved" | "none";
  register: "casual" | "warm" | "terse" | "formal" | "mixed" | "unknown";
};
export type RelationshipUnderstanding = {
  register: ContextualExemplar["register"];
  relationship_kind: "close_friend" | "logistics" | "work" | "family" | "dormant_close" | "other" | "unknown";
  open_thread: string | null;
  last_exchange_shape: "question_from_them" | "statement_from_them" | "statement_from_you" | "plan_unresolved" | "none";
  topics: string[]; cadence_norm: string | null; voice_exemplars: ContextualExemplar[];
};
export type DigestV2 = Omit<Digest, "schema_version" | "relationships"> & {
  schema_version: "digest.v2"; synced_through: ISO8601;
  relationships: Array<Relationship & { understanding: RelationshipUnderstanding }>;
};

export type VoicePack = {
  schema_version: "voice_pack.v1";
  voice_pack_version: string;
  contact_id: string | null;
  scope: "contact" | "global";
  n_exemplars?: number;
  register: {
    median_len_chars: number; p90_len_chars?: number;
    emoji_rate: number; top_emoji?: string[];
    punctuation: "lowercase_no_period" | "lowercase_period" | "sentence_case_no_period" | "sentence_case_period" | "mixed";
    greeting_rate?: number; signoff_rate?: number;
    abbreviations?: string[]; avg_msgs_per_burst: number;
    question_rate?: number; apology_openers?: string[];
  };
  /** THE USER'S OWN SENT MESSAGES ONLY, redacted. is_from_me = 1, always. */
  exemplars: string[];
  as_of: ISO8601;
};

export type VoicePackV2 = Omit<VoicePack, "schema_version" | "exemplars"> & {
  schema_version: "voice_pack.v2"; exemplars: ContextualExemplar[];
};

/** The model may select only this named query during Phase 2. */
export type ChatQuery = { schema_version: "chat_query.v1"; name: "waiting_on_me"; limit?: number };
export type DraftDelivery = {
  schema_version: "draft_delivery.v1"; contact_id: string; text: string;
  recipient: { kind: "resolved"; handle: string } | { kind: "unavailable" };
};
export type ChatLicense = { contact_id: string; display: string; reason: string };
export type ChatReply = {
  schema_version: "chat_reply.v1"; kind: "answer" | "decline"; text: string;
  synced_through: ISO8601; licenses: ChatLicense[]; follow_up_draft?: DraftDelivery;
};

/** §4.2's universal tool-evidence ref returned by every agent tool ({source,id}). Also
 * hand-mirrored in cloud/agent/src/types.ts and cloud/api/src/schemas.ts — see the parity
 * comment on ChatReplyV2 below for why three independent copies of this shape exist and
 * how they're kept from drifting apart. */
export type EvidenceRef = { source: string; id: string };

/**
 * chat_reply.v2 (contracts/schema/chat_reply.v2.json, V3_ARCHITECTURE.md §2/§4.2).
 * ADDITIVE to v1 — `ChatReply` above is UNCHANGED, and every v1 producer/consumer
 * (cloud/chat/src/selector.ts, reply.ts, waiting-on-me.ts) keeps compiling and behaving
 * identically. v2 adds `kind: "open"`: the v3 agent path's verified free-form prose,
 * carrying `evidence` (this file's `EvidenceRef[]`) instead of the closed-vocabulary
 * `licenses` that `answer`/`decline` still use.
 *
 * Until 2026-08-09 this type did not exist here at all: `chat_reply.v2.json` and its zod
 * mirror (`cloud/api/src/schemas.ts`'s `chatReplyV2Schema`) were both schema-validated and
 * differentially tested against each other, but nothing in the runtime type graph could
 * express `kind: "open"` or `evidence` — every consumer had to downgrade a verified agent
 * reply back to v1's `{kind:"answer", licenses:[]}`, silently discarding the evidence refs
 * that make the reply's claims defensible. Integration (Track H) found the gap; this type
 * closes it.
 *
 * Deliberately kept STRUCTURALLY FLAT — matching `z.infer<typeof chatReplyV2Schema>`
 * exactly — rather than re-encoding the JSON Schema's `kind="open"` if/then/else as a TS
 * discriminated union. A more precise hand-written union would diverge from what the zod
 * mirror actually infers and become a THIRD independent copy of the same contract, which
 * is the exact drift class this project keeps shipping (digest.v2's `unknown` enum member,
 * this very gap). `cloud/api/src/schemas.ts` asserts this type is BIDIRECTIONALLY equal to
 * `z.infer<typeof chatReplyV2Schema>` at compile time — see the comment there — so this
 * file cannot drift from the zod mirror without `tsc` failing, the same guarantee
 * `differential.test.ts` gives between the zod mirror and the frozen JSON Schema.
 *
 * The "evidence required, non-empty licenses forbidden, iff kind=open" invariant is
 * enforced by ajv (the JSON Schema) and zod (`.refine()`) at those boundaries; a value
 * constructed directly as this TS type (e.g. Track H's agent-path bridge) is expected to
 * follow it by convention, same as any other producer here relies on a boundary validator
 * rather than the type checker to catch a conditional-requiredness bug.
 */
export type ChatReplyV2 = {
  schema_version: "chat_reply.v2";
  kind: "answer" | "decline" | "open";
  text: string;
  synced_through: ISO8601;
  licenses: ChatLicense[];
  evidence?: EvidenceRef[];
  follow_up_draft?: DraftDelivery;
};

/** Convenience union for code that must accept either wire version — e.g. Track H's
 * bridge from the verified agent path (chat_reply.v2) back into the existing delivery
 * pipeline, which speaks chat_reply.v1 today. Discriminate on `schema_version`. */
export type ChatReplyAny = ChatReply | ChatReplyV2;

export type Gist = {
  schema_version: "gist.v1";
  gist_id: string; contact_id: string; display?: string;
  state: "action_needed" | "fading" | "birthday" | "dormant" | "revived";
  days_silent: number; unanswered_question: boolean;
  topic: string | null; has_deadline: boolean; deadline_hint: string | null;
  gist: string;
  /** The fabrication-gate allowlist. A draft may name a specific only if it is here. */
  facts: { dates: string[]; times: string[]; places: string[]; amounts: string[]; names: string[] };
  priority: number;
  producer: "sql" | "local_model";
  model_id: string | null;
  as_of: ISO8601;
};

export type Candidate = { stance: "answer" | "defer"; text: string; chars: number };

export type DraftBundle = {
  schema_version: "draft_bundle.v1";
  contact_id: string; gist_id: string;
  /** Exactly two, or exactly zero. Zero is a legitimate degraded outcome. */
  candidates: Candidate[];
  model_id: string; prompt_version: string; voice_pack_version: string;
  validator: { passed: boolean; attempts: number; failures: string[] };
  latency_ms?: number | null;
  as_of: ISO8601;
};

export type BriefItem = {
  contact_id: string; display: string;
  headline: string; gist: string;
  remedy: "reply" | "call" | "dismiss" | "snooze";
  drafts: DraftBundle | null;
};

export type Brief = {
  schema_version: "brief.v1";
  user_id: string; scheduled_for: ISO8601;
  staleness: { digest_as_of: ISO8601; hours_stale: number; warn: boolean; message?: string | null };
  items: BriefItem[];   // max 3
  card_url?: string | null;
  /**
   * What the renderer produced, ADDITIVE in prompt 05 alongside the same field in
   * `brief.v1.json`. Optional, so nothing that compiles today stops compiling.
   *
   * Without it the composer carried a URL and no kind, `deliverBrief` could not tell a
   * report card from a refusal card, and a user below the renderer's bar was handed
   * "not enough history yet" every morning forever.
   */
  card_kind?: "standard" | "refusal" | null;
};

export type OutboundBlock =
  | { type: "text"; text: string }
  | { type: "image"; url: string; alt?: string | null }
  | { type: "contact_card"; name: string; handle: string };

export type OutboundMessage = {
  schema_version: "outbound.v1";
  user_id: string; idempotency_key: string;
  blocks: OutboundBlock[];
  reply_to_message_id?: string | null;
  requested_capabilities?: string[];
};

export type InboundMessage = {
  schema_version: "inbound.v1";
  /** Widened for prompt 10: `spectrum`. A union widening; nothing that compiled stops. */
  provider: "linq" | "mock" | "twilio" | "spectrum";
  provider_message_id: string; line_id: string;
  from_handle: string; user_id: string | null;
  received_at: ISO8601;
  kind: "text" | "tapback" | "read_receipt" | "delivery_receipt" | "typing";
  text: string | null; tapback?: string | null;
  reply_to_message_id?: string | null;
  protocol?: null | "imessage" | "rcs" | "sms";
  trace_id?: string | null;
};

export type Capabilities = {
  tapbacks: boolean; images: boolean; groups: boolean;
  typing: boolean; richlinks: boolean; contact_cards: boolean; threading: boolean;
};

export type SendResult = {
  message_id: string;
  provider: string;
  /**
   * **NULLABLE from prompt 10, and this is a widening of a frozen type — not free.**
   * `deliver.ts` and Track C's adapter both read it.
   *
   * Photon reports four services (`iMessage | SMS | RCS | unknown`) against these three
   * protocols. `unknown` must not become `"sms"`: "we do not know whether this was blue"
   * and "this was green" are different facts and only one of them is true, and the wrong
   * one drives the handle-mismatch flag that tells a user their number is not on iMessage.
   *
   * `null` rather than a fourth string, for consistency: `inbound.v1.protocol` already
   * encodes exactly this fact as `null`, so both directions end up with ONE encoding for
   * "we do not know" instead of two.
   */
  protocol: "imessage" | "rcs" | "sms" | null;
  line_id: string;
};

export type ChannelHealth = {
  status: "up" | "degraded" | "banned";
  line_id: string | null;
  checked_at: ISO8601;
};

/**
 * THE most important interface in the system. No provider semantics appear above
 * this line: the composer emits blocks and never learns whether delivery was blue,
 * green or grey.
 *
 * Produced by Track C. Consumed by Track D.
 */
export interface Channel {
  send(msg: OutboundMessage): Promise<SendResult>;
  capabilities(): Promise<Capabilities>;
  health(): Promise<ChannelHealth>;
  /**
   * Throws on signature failure. Never returns a partially-normalized message.
   *
   * `rawBody` is the RAW REQUEST BYTES, before any JSON parsing. Not the parsed
   * object. A signature is computed over bytes, so re-serializing and re-signing a
   * parsed object verifies a different document than the one that arrived — key
   * order alone breaks it.
   *
   * This was typed `unknown` until 2 Aug, which let the transport implementation and
   * the foundation stub disagree about what the argument means without the compiler
   * noticing. That is precisely the disagreement a type at this seam exists to catch.
   *
   * Callers behind Fastify: register a raw-body content-type parser BEFORE the JSON
   * parser and pass `req.rawBody`. And guard the header — `req.headers[...]` is
   * `string | string[] | undefined`, and a missing signature must become
   * `401 bad_signature`, never a 500.
   */
  normalizeInbound(rawBody: Buffer | string, signature: string): InboundMessage;
}

/** A line the transport has assigned to one user. */
export type AssignedLine = {
  /** The transport's own id for the line. */
  line_id: string;
  /** The handle the USER texts. Shared-pool means this differs per recipient. */
  handle: string;
};

/**
 * Registering a user with the transport, and finding out which line they were given.
 *
 * ADDITIVE, AMENDMENT-002. A separate port rather than two more methods on `Channel`,
 * because registration is not a sending concern and `Channel` is the line above which no
 * provider semantics appear. It lives here, beside `Channel`, for one reason worth
 * stating: `cloud/channel` and `cloud/api` both import from `cloud/shared`, and
 * `cloud/channel` has never imported from `cloud/api`. Defining this on the product
 * surface would force `spectrum-channel.ts` to import a type from the API in order to
 * implement it — an inverted arrow that is invisible until the second implementation
 * exists and permanent afterwards.
 *
 * **TWO OPERATIONS, AND IT MUST STAY TWO.** Register these handles for this user; tell
 * me which line is theirs. The moment this acquires a `send`, or learns what a message
 * is, or grows a capability query, the seam has moved and the frozen `Channel` line
 * stops meaning anything — there would be two interfaces that both know how to talk to a
 * transport and no rule about which one owns what. If you are here because you need one
 * more method: the answer is almost certainly a new port, or `Channel`.
 */
export interface Registrar {
  /**
   * Every handle this user might send from, in ONE call.
   *
   * One call rather than one per handle, deliberately: **Messages on a Mac frequently
   * sends from the Apple Account email rather than the phone number**, the transport
   * cannot tell us which Apple will pick, and an API that lets a caller register only
   * one is an API that invites getting it wrong. The failure it prevents is silent —
   * inbound from an unregistered handle looks like nothing happening at all.
   */
  register(input: { user_id: string; handles: readonly string[] }): Promise<void>;

  /**
   * The line assigned to this user, or `null` if they have none yet.
   *
   * Resolving must not send: a "new conversation" is the first message a line SENDS, so
   * reading the assignment has to be free of quota and free of a cold-open message to
   * somebody who has not written first.
   */
  lineFor(userId: string): Promise<AssignedLine | null>;
}
